import{_ as a,o as n,c as t,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Chat slash reference picker","description":"","frontmatter":{},"headers":[],"relativePath":"feature/chat-slash-reference/spec.md","filePath":"feature/chat-slash-reference/spec.md"}'),i={name:"feature/chat-slash-reference/spec.md"};function s(c,e,r,d,l,h){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="chat-slash-reference-picker" tabindex="-1">Chat slash reference picker <a class="header-anchor" href="#chat-slash-reference-picker" aria-label="Permalink to &quot;Chat slash reference picker&quot;">​</a></h1><h2 id="objective-and-acceptance-criteria" tabindex="-1">Objective and acceptance criteria <a class="header-anchor" href="#objective-and-acceptance-criteria" aria-label="Permalink to &quot;Objective and acceptance criteria&quot;">​</a></h2><p>Typing <code>/</code> in the chat composer (same editor as <code>chat-rich-composer</code>) opens a merged, single-list search picker across four entity kinds: Task (including <code>TaskType: POST</code> rows, labelled as content/ấn phẩm in the UI), Media Campaign (<code>media_campaigns</code> / <code>MediaCampaignController</code>), and the existing repository file picker already delivered by <code>chat-attachments</code>. The fourth kind reuses that existing picker instead of a new one. Typing after <code>/</code> filters by name across all kinds at once — no kind must be chosen first. Arrow/Enter/Escape behave like the existing <code>@</code> mention picker (<code>useChatRichEditor</code>); <code>/</code> and <code>@</code> triggers are independent and mutually exclusive at the same caret position.</p><p>A selected result inserts a new atomic, non-editable <code>reference</code> rich-content node (sibling of the existing <code>mention</code> node), carrying <code>refType</code> (<code>TASK</code> | <code>MEDIA_CAMPAIGN</code>), <code>refId</code>, and a denormalized <code>label</code> snapshot for plain-text/search fallback — mirroring how <code>mention</code> nodes snapshot <code>label</code>. File references continue to use the existing attachment flow and are out of scope for the new node type.</p><p>Sent messages render the <code>reference</code> node as a rich preview card (title, status badge, thumbnail/avatar where applicable) instead of plain text, fetched by <code>refId</code> through each domain&#39;s existing viewer-scoped read API (<code>GET /api/v1/workspaces/{workspaceId}/tasks/{taskId}</code>, <code>GET /api/v1/media-campaigns/{campaignId}</code>). Preview data is fetched live at render time per the current viewer&#39;s access, never cached into the stored message — same &quot;deny without leaking name/thumbnail&quot; rule as <code>chat-attachments</code>. A referenced entity the viewer cannot access renders a generic &quot;no access&quot; placeholder, not an error and not the real title.</p><p>Clicking a preview card navigates to that Task or Media Campaign&#39;s own page. That page in turn shows a backlink list of channel messages that reference it (bidirectional), fetched through a new scoped endpoint — see API section. Backlinks are message pointers (channel/thread id + message id), not copies of message content; the list resolves current channel access same as existing deep-link behavior.</p><p>Preview cards expose a small set of inline quick actions matching what the viewer could already do on that entity&#39;s own page under their existing role/permission rules — no action is newly grantable from chat. Scope for v1: Task status transition (reusing the existing allowed-transition rule) and Media Campaign approval action, both already present as standalone APIs. Actions call the existing domain APIs directly; chat has no bespoke mutation path. A failed or forbidden action shows the existing domain error, not a generic chat error.</p><p>When a message containing a <code>reference</code> node is sent, the referenced entity&#39;s assignee (Task) is notified through a new delivery path parallel to <code>chat-mention-inbox</code>&#39;s existing inbox (same DND/mute, dedup against being both assignee and a <code>mention</code> recipient in the same message, same 20- recipient technical cap shared across mentions+references, no backfill for old messages). Media Campaign references do not notify — campaigns have no single assignee field; this may be revisited later. This is additive to the existing mention inbox, not a replacement.</p><h2 id="non-goals" tabindex="-1">Non-goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-goals&quot;">​</a></h2><p>No new &quot;Content/Post&quot; domain — <code>POST</code>-typed tasks are Task rows and use the Task read API. No campaign-detail domain fields beyond what <code>MediaCampaignController</code> already exposes. No write-back from chat to the referenced entity beyond the two quick actions named above. No offline/ cached preview. <code>WorkspaceCampaignController</code>&#39;s <code>campaigns</code> resource is a different resource and is not used here.</p><h2 id="api-and-scope" tabindex="-1">API and scope <a class="header-anchor" href="#api-and-scope" aria-label="Permalink to &quot;API and scope&quot;">​</a></h2><ul><li>Reuse: <code>GET /api/v1/workspaces/{workspaceId}/tasks/{taskId}</code>, <code>GET /api/v1/media-campaigns/{campaignId}</code> for preview card data — add only the slimmed preview fields the card needs if the existing DTOs are heavier than needed for a list of many simultaneous cards in a timeline.</li><li>New: <code>GET /api/v1/workspaces/{workspaceId}/tasks/{taskId}/references</code> and the Media Campaign equivalent — returns paginated backlink pointers (channelId/threadRootId, messageId, snippet-free) for messages that embed a <code>reference</code> node pointing at that entity, scoped to the viewer&#39;s existing channel access.</li><li>New: merged search endpoint (or client-side fan-out to existing Task list / Media Campaign list endpoints filtered by <code>search</code>) — decide in planning whether one new aggregate endpoint or parallel calls fits existing pagination/perf conventions better.</li><li>Extend <code>chat_messages</code> richContent JSON schema/validator to allowlist the new <code>reference</code> node alongside existing <code>mention</code>, mirroring the migration approach already used for <code>richContent</code> (only add the new node to the constraint, never replace/weaken existing constraints or indexes).</li><li>Extend <code>chat-mention-inbox</code>&#39;s delivery path with a reference-notification variant keyed off <code>refType = TASK</code>&#39;s assignee; same preferences API surface (no new preference endpoints), same actor-scoped-only access rule.</li></ul><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><p>New <code>ChatReferenceNode</code> TipTap node beside <code>ChatMentionNode</code> in <code>chatRichContent.ts</code>; picker UI extends <code>useChatRichEditor</code>&#39;s existing suggestion state machine (same <code>box</code>/<code>listId</code>/<code>active</code> pattern) keyed off <code>/</code> instead of <code>@</code>, with a kind icon per result row but a single merged, ranked list. Preview card component is new; quick actions reuse existing Task/Media Campaign mutation hooks already used on their own pages — no new mutation hooks. i18n: <code>chat.rich.reference.*</code> parallel vi/en keys. No emoji icons — <code>lucide-react</code> per project icon rule.</p><h2 id="risks-open-items-for-planning" tabindex="-1">Risks / open items for planning <a class="header-anchor" href="#risks-open-items-for-planning" aria-label="Permalink to &quot;Risks / open items for planning&quot;">​</a></h2><ul><li>Confirm whether the merged search is one new backend aggregate endpoint or a client-side fan-out; affects latency and whether ranking is server- or client-side.</li><li>Confirm the 20-recipient cap is genuinely shared between mention and reference notifications in one message, or counted separately.</li><li>Confirm Media Campaign&#39;s &quot;approval&quot; quick action maps to an existing single API call or a multi-step flow that doesn&#39;t fit an inline card.</li></ul>',16)])])}const g=a(i,[["render",s]]);export{m as __pageData,g as default};
